fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut it = txt.chars().rev();

    let last = match it.next() {
        Some(c) => c,
        None => return false, // empty
    };

    if !last.is_ascii_alphabetic() {
        return false;
    }

    match it.next() {
        None => true,          // exactly one character
        Some(prev) => prev == ' ',
    }
}